begin;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at) values
('fe000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','recovery@security.invalid',now());
insert into public.people(id,display_name) values('fe100000-0000-4000-8000-000000000001','Fictional Recovery Target');
insert into public.auth_identities(person_id,auth_user_id,kind) values('fe100000-0000-4000-8000-000000000001','fe000000-0000-4000-8000-000000000001','employee_email');
insert into public.memberships(person_id,kind,status) values('fe100000-0000-4000-8000-000000000001','employee','active');
insert into public.role_assignments(person_id,role_key,grant_reason) values('fe100000-0000-4000-8000-000000000001','teacher','Fictional recovery regression');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values('fe200000-0000-4000-8000-000000000001','fe000000-0000-4000-8000-000000000001','totp','verified',now(),now());
insert into auth.sessions(id,user_id,aal,created_at,updated_at) values('fe300000-0000-4000-8000-000000000001','fe000000-0000-4000-8000-000000000001','aal1',now()-interval '2 hours',now()),('fe300000-0000-4000-8000-000000000002','fe000000-0000-4000-8000-000000000001','aal1',now(),now());
insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values('fe400000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002','otp',now(),now());
set local role authenticated;
set local request.jwt.claims='{"sub":"fe000000-0000-4000-8000-000000000001","session_id":"fe300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}';
select is(public.current_person_id(),'fe100000-0000-4000-8000-000000000001'::uuid,'owned live employee session resolves');
select throws_ok('select * from public.employee_password_recoveries','42501',null,'private recovery ledger denied');
select throws_ok('select * from public.employee_recovery_throttles','42501',null,'private HMAC throttle ledger denied');
select throws_ok($$select public.prepare_employee_password_recovery('recovery@security.invalid',repeat('a',64),repeat('b',64))$$,'42501',null,'browser cannot select provider identity');
select throws_ok($$select public.claim_employee_password_recovery(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),repeat('a',64))$$,'42501',null,'browser cannot set cutoff/claim');
select throws_ok($$select public.finish_employee_recovery_delivery(gen_random_uuid(),repeat('a',64),true)$$,'42501',null,'browser cannot deliver proof');
select throws_ok($$select public.finish_employee_password_recovery(gen_random_uuid(),gen_random_uuid(),true)$$,'42501',null,'browser cannot confirm provider mutation');
reset role;
delete from auth.sessions where id='fe300000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.current_person_id(),null::uuid,'provider-deleted employee session denied even without application cutoff');
reset role;
set local role anon;
select throws_ok($$select public.prepare_employee_password_recovery('recovery@security.invalid',repeat('a',64),repeat('b',64))$$,'42501',null,'anonymous preparation denied');
select throws_ok($$select public.claim_employee_password_recovery(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),repeat('a',64))$$,'42501',null,'anonymous claim denied');
reset role;
select is((select count(*)::integer from public.prepare_employee_password_recovery('unknown@security.invalid',repeat('c',64),repeat('d',64))),0,'unknown account has no recovery record');
select set_config('test.recovery_id',(select id::text from public.prepare_employee_password_recovery('recovery@security.invalid',repeat('a',64),repeat('b',64))),true);
select is((select count(*)::integer from public.prepare_employee_password_recovery('recovery@security.invalid',repeat('a',64),repeat('b',64))),0,'one-minute reissue denied without changing request');
select lives_ok($$select public.finish_employee_recovery_delivery(current_setting('test.recovery_id')::uuid,repeat('e',64),true)$$,'private proof delivery bound');
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('f',64))$$,'42501',null,'wrong exact-request proof denied');
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,gen_random_uuid(),'fe300000-0000-4000-8000-000000000002',repeat('e',64))$$,'42501',null,'wrong Auth owner denied');
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001',gen_random_uuid(),repeat('e',64))$$,'42501',null,'unknown session denied');
update public.memberships set status='suspended' where person_id='fe100000-0000-4000-8000-000000000001';
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('e',64))$$,'42501',null,'suspended target denied');
update public.memberships set status='active' where person_id='fe100000-0000-4000-8000-000000000001';
update auth.users set email='changed@security.invalid' where id='fe000000-0000-4000-8000-000000000001';
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('e',64))$$,'42501',null,'changed established email denied');
update auth.users set email='recovery@security.invalid' where id='fe000000-0000-4000-8000-000000000001';
update public.employee_password_recoveries set created_at=now()-interval '2 minutes',expires_at=now()-interval '1 minute' where id=current_setting('test.recovery_id')::uuid;
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('e',64))$$,'42501',null,'expired proof denied');
update public.employee_password_recoveries set expires_at=now()+interval '30 minutes' where id=current_setting('test.recovery_id')::uuid;
update auth.mfa_amr_claims set authentication_method='password' where id='fe400000-0000-4000-8000-000000000001';
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('e',64))$$,'42501',null,'non-email password session denied');
update auth.mfa_amr_claims set authentication_method='otp' where id='fe400000-0000-4000-8000-000000000001';
select set_config('test.recovery_execution',(select execution_key::text from public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('e',64))),true);
select is((select status from public.employee_password_recoveries where id=current_setting('test.recovery_id')::uuid),'executing','proof claims only one mutation');
select ok(exists(select 1 from public.auth_session_cutoffs where auth_user_id='fe000000-0000-4000-8000-000000000001'),'cutoff commits before provider update');
select throws_ok($$select public.claim_employee_password_recovery(current_setting('test.recovery_id')::uuid,'fe000000-0000-4000-8000-000000000001','fe300000-0000-4000-8000-000000000002',repeat('e',64))$$,'42501',null,'concurrent/replayed claim denied');
insert into auth.sessions(id,user_id,aal,created_at,updated_at) values('fe300000-0000-4000-8000-000000000003','fe000000-0000-4000-8000-000000000001','aal1',clock_timestamp(),clock_timestamp());
-- Model a stalled provider mutation that outlives the claimed link. Expiry is NOT a fence.
update public.employee_password_recoveries set created_at=now()-interval '2 hours',expires_at=now()-interval '1 hour' where id=current_setting('test.recovery_id')::uuid;
select is((select count(*)::integer from public.prepare_employee_password_recovery('recovery@security.invalid',repeat('a',64),repeat('b',64))),0,'expired in-flight mutation cannot be superseded by a second provider update');
select is((select status from public.employee_password_recoveries where id=current_setting('test.recovery_id')::uuid),'executing','stalled provider mutation stays exclusively claimed');
set local role authenticated;
set local request.jwt.claims='{"sub":"fe000000-0000-4000-8000-000000000001","session_id":"fe300000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}';
select is(public.current_person_id(),null::uuid,'even a new sign-in is denied while password mutation outcome is uncertain');
reset role;
select throws_ok($$select public.finish_employee_password_recovery(current_setting('test.recovery_id')::uuid,gen_random_uuid(),true)$$,'42501',null,'wrong execution receipt denied');
select is(public.finish_employee_password_recovery(current_setting('test.recovery_id')::uuid,current_setting('test.recovery_execution')::uuid,true),true,'confirmed mutation completes');
set local role authenticated;
set local request.jwt.claims='{"sub":"fe000000-0000-4000-8000-000000000001","session_id":"fe300000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}';
select is(public.current_person_id(),null::uuid,'session created inside provider mutation window is blocked by final cutoff');
reset role;
select is((select count(*)::integer from auth.mfa_factors where user_id='fe000000-0000-4000-8000-000000000001' and status='verified'),1,'MFA factor preserved');
select is((select count(*)::integer from public.role_assignments where person_id='fe100000-0000-4000-8000-000000000001' and role_key='teacher' and revoked_at is null),1,'role unchanged');
select throws_ok($$select public.finish_employee_password_recovery(current_setting('test.recovery_id')::uuid,current_setting('test.recovery_execution')::uuid,true)$$,'42501',null,'completion replay denied');
update public.employee_recovery_throttles set attempts=5 where identifier_hash=repeat('a',64);
select is((select count(*)::integer from public.prepare_employee_password_recovery('recovery@security.invalid',repeat('a',64),repeat('b',64))),0,'sixth recipient request denied');
select is((select attempts from public.employee_recovery_throttles where identifier_hash=repeat('a',64)),6,'recipient budget persists for denied attempts');
update public.employee_recovery_throttles set attempts=100 where identifier_hash=repeat('b',64);
select is((select count(*)::integer from public.prepare_employee_password_recovery('recovery@security.invalid',repeat('c',64),repeat('b',64))),0,'shared local budget denies attempt101 despite another recipient hash');
select is((select count(*)::integer from public.employee_password_recoveries where auth_user_id='fe000000-0000-4000-8000-000000000001'),1,'throttled request cannot replace completed recovery');
update public.employee_recovery_throttles set attempts=5,window_started_at=now()-interval '2 hours' where identifier_hash=repeat('a',64);
update public.employee_recovery_throttles set attempts=100,window_started_at=now()-interval '2 hours' where identifier_hash=repeat('b',64);
select is((select count(*)::integer from public.prepare_employee_password_recovery('unknown@security.invalid',repeat('a',64),repeat('b',64))),0,'expired budget still does not invent unknown account');
select is((select attempts from public.employee_recovery_throttles where identifier_hash=repeat('a',64)),1,'recipient window resets only after expiry');
select * from finish();
rollback;
